Step.Calculation:
JSONSetElement ( "{}" ;
	[ "test"     ; "Create kalkulacija"                                                                                                                   ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "success" and not IsEmpty ( JSONGetElement ( $result ; "data.kalkulacijaID" ) ) ; "pass" ; "error" ) ; JSONString ] ;
	[ "result"   ; $result                                                                                                                                ; JSONObject ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Create duplicate (idempotent)"                                                                                                        ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "success" and JSONGetElement ( $result ; "data.kalkulacijaID" ) = $kalkulacijaID ; "pass" ; "error" ) ; JSONString ] ;
	[ "result"   ; $result                                                                                                                                ; JSONObject ] ;
	[ "note"     ; "Expected: success + same kalkulacijaID. Must not create a duplicate."                                                                 ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Generate stavke"                                                                                     ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "success" and $stavkeCount > 0 ; "pass" ; "error" )   ; JSONString ] ;
	[ "result"   ; $result                                                                                               ; JSONObject ]
)

Value.Calculation:
epSQLExecute (
	"SELECT COUNT(*) FROM KMP__Stavke s, KMP__SKMP_StavkePrimke sp
	 WHERE s.PrimaryKey = sp.PrimaryKey AND s.ForeignKeyKalkulacijaID = ?
	 AND (sp.ProdajnaCijena IS NULL OR sp.ProdajnaCijena <= 0)" ;
	"useSQLResult=pdcchk" ;
	$kalkulacijaID
)

Step.Calculation:
JSONSetElement ( "{}" ;
	[ "test"     ; "Verify ProdajnaCijena set on all stavke"                                                            ; JSONString ] ;
	[ "severity" ; Case ( $badPDC = 0 ; "pass" ; "error" )                                                             ; JSONString ] ;
	[ "result"   ; JSONSetElement ( "{}" ; "stavkeWithBadProdajnaCijena" ; $badPDC ; JSONNumber )                       ; JSONObject ] ;
	[ "note"     ; "Expected: 0 stavke with null or zero ProdajnaCijena. GenerateStavke must write-back when correcting below-cost." ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Generate again (guard: ALREADY_GENERATED)"                                       ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "fail" ; "pass" ; "error" )       ; JSONString ] ;
	[ "result"   ; $result                                                                            ; JSONObject ] ;
	[ "note"     ; "Expected: fail — stavke already exist for this kalkulacija."                     ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Post kalkulacija"                                                                                                                                               ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "success" and GetAsNumber ( JSONGetElement ( $result ; "data.ukupnoMP_Roba" ) ) > 0 ; "pass" ; "error" )         ; JSONString ] ;
	[ "result"   ; $result                                                                                                                                                          ; JSONObject ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "LockedSelling = 1 after Post"                                                                                   ; JSONString ] ;
	[ "severity" ; Case ( $kmpStatusAfterPost = "Knjižena" ; "pass" ; "error" )                                                    ; JSONString ] ;
	[ "result"   ; JSONSetElement ( "{}" ; "kmpStatus" ; $kmpStatusAfterPost ; JSONString )                                         ; JSONObject ] ;
	[ "note"     ; "Expected: KMP Status = Knjižena — LockedSelling calc derives from this."                                        ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "stavkaPrimkeID" ; $sampleStavkaPK ; JSONString ] ;
	[ "newPrice"       ; 99,99           ; JSONNumber ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "SP__SetProdajnaCijena (guard: LOCKED)"                                                                ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "fail" and $prodajnaAfterSP ≠ 99,99 ; "pass" ; "error" ) ; JSONString ] ;
	[ "result"   ; JSONSetElement ( "{}" ;
		[ "spStatus"      ; JSONGetElement ( $result ; "status" )                       ; JSONString ] ;
		[ "errorCode"     ; JSONGetElement ( $result ; "messages.error[0].code" )       ; JSONString ] ;
		[ "prodajnaBefore" ; $prodajnaBeforeSP                                         ; JSONNumber ] ;
		[ "prodajnaAfter"  ; $prodajnaAfterSP                                          ; JSONNumber ] ;
		[ "sampleStavkaPK" ; $sampleStavkaPK                                           ; JSONString ]
	)                                                                                                                     ; JSONObject ] ;
	[ "note"     ; "Expected: SP fails + ProdajnaCijena not changed to 99,99."                                            ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Post again (guard: INVALID_STATUS)"                                              ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "fail" ; "pass" ; "error" )       ; JSONString ] ;
	[ "result"   ; $result                                                                            ; JSONObject ] ;
	[ "note"     ; "Expected: fail — Status is already Knjižena."                                   ; JSONString ]
)

Value.Calculation:
JSONSetElement ( "{}" ;
	[ "kalkulacijaID"  ; KMP__KalkulacijaMP::PrimaryKey    ; JSONString ] ;
	[ "status"         ; KMP__KalkulacijaMP::Status        ; JSONString ] ;
	[ "ukupnoMP_Roba"  ; KMP__KalkulacijaMP::UkupnoMP_Roba ; JSONNumber ] ;
	[ "stavkeCount"    ; $stavkeCount                       ; JSONNumber ]
)

Step.Calculation:
JSONSetElement ( "{}" ;
	[ "test"     ; "Verify final state"                                                                                                                  ; JSONString ] ;
	[ "severity" ; Case ( KMP__KalkulacijaMP::Status = "Knjižena" and KMP__KalkulacijaMP::UkupnoMP_Roba > 0 ; "pass" ; "error" )                        ; JSONString ] ;
	[ "result"   ; $verify                                                                                                                               ; JSONObject ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Verify final state"                                                                                  ; JSONString ] ;
	[ "severity" ; "error"                                                                                               ; JSONString ] ;
	[ "result"   ; JSONSetElement ( "{}" ; "error" ; "Record not found for PK: " & $kalkulacijaID ; JSONString )         ; JSONObject ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "RefreshTotals (regression)"                                                                          ; JSONString ] ;
	[ "severity" ; Case ( Get ( FoundCount ) = 1 and KMP__KalkulacijaMP::UkupnoMP_Roba > 0 ; "pass" ; "error" )         ; JSONString ] ;
	[ "result"   ; JSONSetElement ( "{}" ; "ukupnoMP_Roba" ; KMP__KalkulacijaMP::UkupnoMP_Roba ; JSONNumber )            ; JSONObject ] ;
	[ "note"     ; "UkupnoMP_Roba must remain > 0 after RefreshTotals runs on a Knjižena record."                        ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Delete kalkulacija"                                                                                                                          ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "success" and not IsEmpty ( JSONGetElement ( $result ; "data.kalkulacijaID" ) ) ; "pass" ; "error" ) ; JSONString ] ;
	[ "result"   ; $result                                                                                                                                       ; JSONObject ] ;
	[ "note"     ; "Expected: success + data.kalkulacijaID returned."                                                                                            ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "LockedSelling cleared after Delete"                                                                                         ; JSONString ] ;
	[ "severity" ; Case ( $kmpStatusAfterDelete ≠ "Knjižena" ; "pass" ; "error" )                                                              ; JSONString ] ;
	[ "result"   ; JSONSetElement ( "{}" ; "kmpStatus" ; $kmpStatusAfterDelete ; JSONString )                                                   ; JSONObject ] ;
	[ "note"     ; "Expected: KMP record gone — Status empty, LockedSelling calc = 0."                                                          ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "test"     ; "Delete again (guard: NOT_FOUND)"                                                 ; JSONString ] ;
	[ "severity" ; Case ( JSONGetElement ( $result ; "status" ) = "fail" ; "pass" ; "error" )       ; JSONString ] ;
	[ "result"   ; $result                                                                            ; JSONObject ] ;
	[ "note"     ; "Expected: fail — KalkulacijaMP was already deleted."                             ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "label" ; "Test__KMP_Flow" ; JSONString ] ;
	[ "vars"  ; JSONSetElement ( "{}" ;
		[ "kalkulacijaID"   ; $kalkulacijaID   ; JSONString ] ;
		[ "stavkeCount"     ; $stavkeCount     ; JSONNumber ] ;
		[ "sampleStavkaPK" ; $sampleStavkaPK  ; JSONString ] ;
		[ "log"             ; $$log            ; JSONRaw    ]
	) ; JSONRaw ]
)
